                            seen[nr][nc] = True
                            stack.append((nr, nc))
                components.append(cells)

    singletons = []
    templates = []

    for comp in components:
        if len(comp) == 1:
            r, c, v = comp[0]
            singletons.append((r, c, v))
        else:
            counts = Counter(v for _, _, v in comp)
            marker_colors = [color for color, cnt in counts.items() if cnt == 1]
            marker_pos = {}
            for r, c, v in comp:
                if counts[v] == 1:
                    marker_pos[v] = (r, c)
            if marker_colors:
                templates.append({
                    "cells": comp,
                    "marker_colors": tuple(sorted(marker_colors)),
                    "marker_pos": marker_pos
                })

    # Index singleton positions by color
    singletons_by_color = defaultdict(list)
    for r, c, v in singletons:
        singletons_by_color[v].append((r, c))

