    syms = [
        lambda r, c: (r, c),
        lambda r, c: (r, -c),
        lambda r, c: (-r, c),
        lambda r, c: (-r, -c),
        lambda r, c: (c, r),
        lambda r, c: (c, -r),
        lambda r, c: (-c, r),
        lambda r, c: (-c, -r),
    ]

    def build_candidate(template, target_map):
        colors = template["marker_colors"]
        anchor = colors[0]
        sr0, sc0 = template["marker_pos"][anchor]
        tr0, tc0 = target_map[anchor]

