            if ok:
                return placed
        return None

    # Build candidate target assignments for each template
    all_candidates = []
    for tmpl in templates:
        colors = tmpl["marker_colors"]
        if any(len(singletons_by_color[c]) == 0 for c in colors):
            all_candidates.append([])
            continue

        candidates = []
