                continue
            placed = build_candidate(tmpl, target_map)
            if placed is not None:
                candidates.append((used, placed))
        all_candidates.append(candidates)

    # Backtracking to choose disjoint target groups
    n = len(templates)
    solution = [None] * n

    order = sorted(range(n), key=lambda i: len(all_candidates[i]))

    def dfs(k, used_targets):
        if k == len(order):
            return True
        i = order[k]
        for target_cells, placed in all_candidates[i]:
