                continue
            solution[i] = placed
            if dfs(k + 1, used_targets | target_cells):
                return True
            solution[i] = None
        return False

    dfs(0, set())

    out = [[0] * w for _ in range(h)]
    for placed in solution:
        if placed is None:
            continue
        for r, c, v in placed:
            out[r][c] = v
    return out

